sql_queries.sql:
SELECT a.account_id, a.account_name, a.customer_level, a.owner_id, a.credit_code, c.customer_no, c.customer_name, c.credit_code AS erp_credit
FROM crm_accounts a LEFT JOIN erp_customers c ON a.credit_code = c.credit_code
WHERE a.customer_level IN ('VIP','vip');

